// @generated by `contract-codegen`. DO NOT EDIT BY HAND.
//
// Regenerate with `npm run gen:contract` in the contracts repository (which
// runs `cargo run -p contract-codegen` and formats the output). The source of
// truth is the Rust contract types in `crates/contracts`, which derive
// `ts_rs::TS` + `schemars::JsonSchema` behind their `contract` feature. The
// JSON Schemas under `schema/` are generated from the same types in the same
// pass.

/**
 * `<slug>/suite.toml`: a suite's identity, declared once for the whole suite.
 *
 * It sits at the root of the suite folder rather than inside any suite tree, so
 * every draft and every exported version of the suite shares it, and renaming the
 * suite renames each of them.
 */
export type SuiteManifest = {
  /**
   * The suite's stable identity: a kebab-case token matching the suite folder.
   */
  slug: string;
  /**
   * The display name shown wherever the suite is presented, including for each
   * of its exported versions.
   */
  name: string;
};

/**
 * `version.toml`: what distinguishes one suite tree, and the prose presenting it.
 *
 * Every path it names is relative to the suite tree and resolves inside it, so a
 * suite tree stays self-contained.
 */
export type VersionManifest = {
  /**
   * The suite version in semver form, matching the name of the exported
   * version folder with its leading `v` removed. Export writes it, and a draft
   * omits it.
   */
  version?: string;
  /**
   * Classification tags, for filtering. Empty when the key is omitted.
   */
  tags?: Array<string>;
  /**
   * A one-line abstract, authored inline as plain text.
   */
  summary: string;
  /**
   * The relative path of the Markdown file describing the suite.
   */
  description: string;
  /**
   * The relative path of the Markdown file recording what changed in this
   * version.
   */
  changelog: string;
  /**
   * Whether the version is still being iterated on. A deployment offers an
   * experimental version only when it opts in.
   */
  experimental?: boolean;
};

/**
 * How a requirement is decided.
 */
export type SuiteRequirementKind = "functional" | "non-functional";

/**
 * One `[[requirement]]` of a specification, written in RFC 2119 style.
 */
export type SuiteRequirement = {
  /**
   * Kebab-case identity, unique within the file. Requirement identity across
   * the suite is `<specification id>/<requirement id>`.
   */
  id: string;
  /**
   * Whether the requirement is decided by a validator or by review.
   */
  kind: SuiteRequirementKind;
  /**
   * The requirement statement, a complete RFC 2119 sentence with the keyword
   * capitalized inside it.
   */
  text: string;
  /**
   * Validator module paths relative to `validators/`, each naming a `.ts` file
   * exporting a validator function. A functional requirement declares one or
   * more; a non-functional one declares none.
   */
  validators?: Array<string>;
};

/**
 * `specifications/<name>/specification.toml`: one specification and the ordered
 * requirements derived from its prose.
 */
export type SpecificationManifest = {
  /**
   * Kebab-case identity, unique among every specification in the suite
   * including nested ones.
   */
  id: string;
  /**
   * The display name used wherever the specification is presented.
   */
  name: string;
  /**
   * A single inline plain-text line describing what the specification covers.
   */
  summary: string;
  /**
   * Where the rendered specification is seeded in the run workspace, relative
   * to `specs/`.
   */
  path: string;
  /**
   * The requirements, in the order they are presented. Emitted as repeated
   * `[[requirement]]` tables.
   */
  requirement?: Array<SuiteRequirement>;
};

/**
 * How a requirement was decided for one run.
 */
export type RequirementStatus = "passed" | "failed" | "undecided";

/**
 * One assertion a validator returned, as the validator stated it.
 *
 * Retaining each assertion rather than a single verdict is what lets a console show
 * the conditions that ran: an implementation satisfying two of a validator's three
 * conditions is visibly different from one satisfying none.
 */
export type RequirementAssertion = {
  /**
   * What the assertion checks, phrased so it reads true when it passes.
   */
  name: string;
  /**
   * Whether the condition held.
   */
  passed: boolean;
  /**
   * The explanation the validator supplied for a failure, when it supplied one.
   */
  detail?: string;
};

/**
 * What one requirement of the specifications a test case covers came to for one
 * run.
 *
 * Keyed by the requirement's suite-wide identity, `<specification id>/<requirement
 * id>` — the same form the seeded specification document writes each requirement
 * under, so a reader of the document and a reader of a result name the same thing.
 */
export type RequirementOutcome = {
  /**
   * The requirement's suite-wide identity: `<specification id>/<requirement id>`.
   */
  id: string;
  /**
   * The id of the specification declaring the requirement.
   */
  specification: string;
  /**
   * The requirement's own id, unique within its specification.
   */
  requirement: string;
  /**
   * Whether the requirement is decided by validators or by review.
   */
  kind: SuiteRequirementKind;
  /**
   * What the validators decided, or that nothing did.
   */
  status: RequirementStatus;
  /**
   * The validator module paths the requirement claims, relative to `validators/`,
   * in the order it lists them. Empty for a non-functional requirement, which
   * claims none.
   */
  validators?: Array<string>;
  /**
   * Every assertion the claimed validators returned, in validator order. Empty
   * when nothing ran.
   */
  assertions?: Array<RequirementAssertion>;
  /**
   * Why the requirement is not decided by its assertions alone: a validator that
   * raised, a validator the project reported nothing for, the reason the project
   * could not be run, or the note that review decides this one.
   */
  detail?: string;
};

/**
 * Whether a debug API function reads state or writes it.
 */
export type DebugApiFunctionKind = "query" | "command";

/**
 * A `[[function.parameter]]` table: one documented parameter of a debug API
 * function.
 */
export type DebugApiParameter = {
  /**
   * The parameter's name, as it appears in the signature.
   */
  name: string;
  /**
   * What the parameter carries.
   */
  description: string;
};

/**
 * A `[[function]]` table: one query or command on a debug API module.
 */
export type DebugApiFunction = {
  /**
   * The property name the function is called by, unique within its module.
   */
  name: string;
  /**
   * Whether the function reports state or changes it.
   */
  kind: DebugApiFunctionKind;
  /**
   * The function's TypeScript signature, carried as a string and copied
   * through verbatim into the generated declaration.
   */
  signature: string;
  /**
   * What a query reports, or what a command changes.
   */
  description: string;
  /**
   * The parameters worth describing, as repeated `[[function.parameter]]`
   * tables.
   */
  parameter?: Array<DebugApiParameter>;
};

/**
 * A `[[module]]` table: the reference from a parent module to the file declaring
 * a child. Each module file is referenced by exactly one parent, so the files
 * form the same tree the debug API does.
 */
export type DebugApiModuleRef = {
  /**
   * The property name the module is reached by on its parent.
   */
  name: string;
  /**
   * The file declaring it, relative to the suite tree.
   */
  path: string;
  /**
   * What the module covers.
   */
  description: string;
};

/**
 * A debug API module: `debug-api.toml` at the root of the version folder, or one
 * of the `debug-api/<path>.toml` files it references.
 *
 * One type serves both, with `handle` present only at the root. The root object
 * is what the implementation sets on `globalThis`, and validators reach the whole
 * tree through it.
 */
export type DebugApiModule = {
  /**
   * The `globalThis` property name the implementation sets the root object on.
   * Declared by `debug-api.toml` alone.
   */
  handle?: string;
  /**
   * What this module covers.
   */
  description: string;
  /**
   * The functions this module defines, as repeated `[[function]]` tables.
   */
  function?: Array<DebugApiFunction>;
  /**
   * The child modules this module reaches, as repeated `[[module]]` tables. A
   * module declaring one is an interior node; a module declaring only
   * functions is a leaf.
   */
  module?: Array<DebugApiModuleRef>;
};

/**
 * What an asset holds, and the test case type that produces it.
 */
export type SuiteAssetKind =
  | "sprite"
  | "sprite-sheet"
  | "voxel"
  | "blender"
  | "particle"
  | "music"
  | "audio-fx";

/**
 * `assets/<asset-id>/asset.toml`: one bundled asset of the suite's finished
 * asset set.
 *
 * Every path it names is relative to the asset's own folder and resolves inside
 * it, so an asset folder stays self-contained.
 */
export type AssetManifest = {
  /**
   * Kebab-case identity, unique across the suite and identical to the folder
   * name.
   */
  id: string;
  /**
   * The display name used wherever the asset is presented.
   */
  name: string;
  /**
   * The asset's format, which is also the test case type that produces it.
   */
  kind: SuiteAssetKind;
  /**
   * The `id` of the specification describing this asset, resolved suite-wide.
   * The value is the id itself and carries no separators.
   */
  specification: string;
  /**
   * The asset's files, relative to the asset folder. At least one.
   */
  files: Array<string>;
};

/**
 * `demos/<slug>/demo.toml`: one demonstration, a short self-contained Vite
 * project showing a single mechanic in practice.
 */
export type DemoManifest = {
  /**
   * Kebab-case identity, matching the demonstration's directory name.
   */
  id: string;
  /**
   * The display name shown wherever the demonstration is presented.
   */
  name: string;
  /**
   * A one-line abstract, authored inline as plain text.
   */
  summary: string;
  /**
   * The `id` of the specification whose mechanic this demonstrates, which is
   * what binds a demonstration to what it illustrates.
   */
  specification: string;
};

/**
 * One `[[media]]` table of a `showcase.toml`.
 */
export type ShowcaseMediaEntry = {
  /**
   * The media file's name in the showcase directory itself. A plain file name,
   * so it carries no path separators.
   */
  file: string;
  /**
   * The short caption displayed with the entry.
   */
  name: string;
};

/**
 * `showcase/showcase.toml`: the ordered carousel of a showcase directory.
 *
 * This is the shared showcase format — the run, case and suite showcases are one
 * format, so this type is the manifest of all three. The bounds that go with it
 * are shared too: the description is capped at
 * [`MAX_SHOWCASE_DESCRIPTION_BYTES`](crate::MAX_SHOWCASE_DESCRIPTION_BYTES), the
 * carousel at [`MAX_SHOWCASE_MEDIA_ENTRIES`](crate::MAX_SHOWCASE_MEDIA_ENTRIES),
 * and each media file at
 * [`MAX_SHOWCASE_MEDIA_FILE_BYTES`](crate::MAX_SHOWCASE_MEDIA_FILE_BYTES).
 *
 * Unknown keys are tolerated: a run-side manifest is model-written, and a stray
 * extra key is not worth losing the whole showcase over.
 */
export type ShowcaseManifest = {
  /**
   * The carousel, as repeated `[[media]]` tables. Table order is carousel
   * order.
   */
  media?: Array<ShowcaseMediaEntry>;
};

/**
 * The kind of test case a definition declares.
 *
 * The `performance`, `adversarial` and `puzzle` forms are specified as TBD on
 * their documentation page: the model carries their `type` value and their common
 * keys, and declares no type table for them.
 */
export type SuiteTestCaseType =
  | "end-to-end"
  | "full-stack"
  | "sprite"
  | "voxel"
  | "blender"
  | "particle"
  | "music"
  | "audio-fx"
  | "performance"
  | "adversarial"
  | "puzzle";

/**
 * How hard a test case is.
 */
export type SuiteDifficulty = "easy" | "medium" | "hard";

/**
 * The `[sprite]` table of a sprite test case definition.
 */
export type SpriteCase = {
  /**
   * The id of the asset under `assets/` the model produces.
   */
  id: string;
  /**
   * Whether the produced asset is a sprite sheet rather than a single sprite.
   */
  sheet?: boolean;
};

/**
 * The `[voxel]` table of a voxel test case definition.
 */
export type VoxelCase = {
  /**
   * The id of the asset under `assets/` the model produces.
   */
  id: string;
  /**
   * Whether rigid-body animation of the produced model is required.
   */
  animated?: boolean;
};

/**
 * The type table of an asset-producing test case whose only key is the asset it
 * targets: `[blender]`, `[particle]`, `[music]` and `[audio-fx]`.
 */
export type AssetCase = {
  /**
   * The id of the asset under `assets/` the model produces.
   */
  id: string;
};

/**
 * The `[build]` table: the commands producing the served static build.
 */
export type BuildCommands = {
  /**
   * Installs the produced implementation's dependencies.
   */
  install: string;
  /**
   * Produces the static build.
   */
  build: string;
};

/**
 * The `[toolchain]` table: the TypeScript commands run over the produced
 * implementation.
 */
export type ToolchainCommands = {
  /**
   * Typechecks the implementation. Required, and a non-zero exit rates the run
   * broken.
   */
  typecheck: string;
  /**
   * Lints the implementation. Recorded rather than gating.
   */
  lint?: string;
  /**
   * Format-checks the implementation. Recorded rather than gating.
   */
  format?: string;
  /**
   * Runs the implementation's own tests. Recorded rather than gating.
   */
  test?: string;
};

/**
 * `test-cases/<name>.toml`: one individually runnable segment of the suite.
 *
 * The file stem is the definition's slug. Every path a definition names is
 * relative to the suite tree.
 */
export type SuiteTestCaseDefinition = {
  /**
   * The display name shown wherever the test case is listed.
   */
  name: string;
  /**
   * The test case type, which decides which type table the definition carries.
   */
  type: SuiteTestCaseType;
  /**
   * The difficulty of this test case.
   */
  difficulty: SuiteDifficulty;
  /**
   * The engine slugs a run may select one entry from. Declared by the
   * code-producing types; empty on the others.
   */
  engines?: Array<string>;
  /**
   * The specification ids this test case covers. `None` — the key omitted —
   * covers every specification in the suite, which is why an absent key is not
   * the same value as an empty list.
   */
  specifications?: Array<string>;
  /**
   * The Handlebars template under the version folder whose rendering is handed
   * to the harness.
   */
  prompt: string;
  /**
   * The cap on the session in hours. A run exceeding it is stopped.
   */
  max_runtime_hours?: number;
  /**
   * Whether the definition is kept out of the catalog for deployments that
   * have not opted in.
   */
  experimental?: boolean;
  /**
   * The command run inside the run container once the workspace and
   * specifications are seeded and before the harness starts. `None` runs no
   * init step. Must not be blank when declared.
   */
  init?: string;
  /**
   * The `[sprite]` table, carried by a `sprite` definition.
   */
  sprite?: SpriteCase;
  /**
   * The `[voxel]` table, carried by a `voxel` definition.
   */
  voxel?: VoxelCase;
  /**
   * The `[blender]` table, carried by a `blender` definition.
   */
  blender?: AssetCase;
  /**
   * The `[particle]` table, carried by a `particle` definition.
   */
  particle?: AssetCase;
  /**
   * The `[music]` table, carried by a `music` definition.
   */
  music?: AssetCase;
  /**
   * The `[audio-fx]` table, carried by an `audio-fx` definition.
   */
  "audio-fx"?: AssetCase;
  /**
   * `[workspaces]`: one entry per engine the definition declares, mapping an
   * engine slug to the starter workspace seeded at the run root. Declared by
   * the code-producing types.
   */
  workspaces?: { [key in string]: string };
  /**
   * `[build]`: the commands that turn the produced implementation into the
   * served static build the validators run against.
   */
  build?: BuildCommands;
  /**
   * `[toolchain]`: the TypeScript commands run over the produced
   * implementation.
   */
  toolchain?: ToolchainCommands;
};

/**
 * One specification folder: its manifest, the prose beside it, and the
 * specification folders nested inside it.
 */
export type SpecificationFolder = {
  /**
   * The folder, relative to the suite tree.
   */
  dir: string;
  /**
   * `specification.toml`.
   */
  manifest: SpecificationManifest;
  /**
   * The declared path of `specification.md`, relative to the suite tree.
   * The prose itself is referenced rather than held, and a save leaves its
   * bytes alone.
   */
  prose: string;
  /**
   * The specification folders nested inside this one. Specification folders
   * nest freely.
   */
  children: Array<SpecificationFolder>;
};

/**
 * The debug API tree: the root module and every module file the version holds.
 */
export type SuiteDebugApi = {
  /**
   * `debug-api.toml`, the only module declaring a `handle`.
   */
  root: DebugApiModule;
  /**
   * The module files under `debug-api/`, keyed by their path relative to the
   * version folder — which is exactly the string a parent's `[[module]]`
   * table names.
   */
  modules: { [key in string]: DebugApiModule };
};

/**
 * One test case definition file.
 */
export type SuiteTestCaseFile = {
  /**
   * The file stem, which is the definition's slug.
   */
  slug: string;
  /**
   * The definition itself.
   */
  definition: SuiteTestCaseDefinition;
};

/**
 * One asset folder.
 */
export type AssetFolder = {
  /**
   * The folder, relative to the suite tree. Its last segment is the
   * asset's id.
   */
  dir: string;
  /**
   * `asset.toml`.
   */
  manifest: AssetManifest;
};

/**
 * One demonstration folder.
 */
export type DemoFolder = {
  /**
   * The folder, relative to the suite tree.
   */
  dir: string;
  /**
   * `demo.toml`.
   */
  manifest: DemoManifest;
};

/**
 * The suite showcase: the carousel, and the declared path of the prose beside
 * it.
 */
export type SuiteShowcase = {
  /**
   * `showcase/showcase.toml`, the carousel.
   */
  manifest: ShowcaseManifest;
  /**
   * The declared path of `showcase.md`, relative to the suite tree.
   */
  description: string;
  /**
   * The media files sitting in the showcase directory, relative to the version
   * folder.
   */
  media: Array<string>;
};

/**
 * The paths of the trees a version folder holds that are not TOML entities.
 *
 * They are recorded rather than parsed: what a reader needs from them is which
 * files are there, and the files themselves belong to the toolchains that
 * consume them.
 */
export type SuiteTrees = {
  /**
   * Every file under `validators/`, relative to the suite tree. The Vitest
   * project rooted there holds the validator modules and their own tests.
   */
  validators: Array<string>;
  /**
   * The reference implementations, keyed by the engine folder name under
   * `reference-implementations/`, each holding that project's files relative
   * to the suite tree.
   */
  reference_implementations: { [key in string]: Array<string> };
  /**
   * The starter workspaces, keyed by the workspace slug under `workspaces/`,
   * each holding that workspace's files relative to the suite tree.
   */
  workspaces: { [key in string]: Array<string> };
  /**
   * Every file under `prompts/`, relative to the suite tree.
   */
  prompts: Array<string>;
  /**
   * Every file under `demos/shared/`, the TypeScript library the
   * demonstrations depend on, relative to the suite tree.
   */
  shared_demos: Array<string>;
};

/**
 * One whole suite tree: the suite it belongs to, every entity the tree declares,
 * and the paths of the trees that hold no TOML.
 */
export type SuiteVersion = {
  /**
   * `suite.toml`: the identity of the suite this tree belongs to. It is read from
   * the suite folder rather than from the tree, so a save of the tree leaves it
   * alone.
   */
  suite: SuiteManifest;
  /**
   * `version.toml`: the version's identity and the prose describing it.
   */
  manifest: VersionManifest;
  /**
   * The specification folders under `specifications/`, nested as they are on
   * disk.
   */
  specifications: Array<SpecificationFolder>;
  /**
   * The debug API, when the version declares one. A version declaring no test
   * case whose subject is a model-written build declares none.
   */
  debug_api?: SuiteDebugApi;
  /**
   * The test case definitions under `test-cases/`, one per file.
   */
  test_cases: Array<SuiteTestCaseFile>;
  /**
   * The bundled assets under `assets/`, one per folder.
   */
  assets: Array<AssetFolder>;
  /**
   * The demonstrations under `demos/`, one per folder.
   */
  demos: Array<DemoFolder>;
  /**
   * The showcase, when the version holds one.
   */
  showcase?: SuiteShowcase;
  /**
   * The trees the model references but does not hold.
   */
  trees: SuiteTrees;
};

/**
 * `version.toml`, with every required key optional.
 */
export type PartialVersionManifest = {
  /**
   * The suite version in semver form. Export writes it, and a draft omits it.
   */
  version?: string;
  /**
   * Classification tags, for filtering. Empty when the key is omitted.
   */
  tags?: Array<string>;
  /**
   * A one-line abstract, authored inline as plain text. Required.
   */
  summary?: string;
  /**
   * The relative path of the Markdown file describing the suite. Required.
   */
  description?: string;
  /**
   * The relative path of the Markdown file recording what changed in this
   * version. Required.
   */
  changelog?: string;
  /**
   * Whether the version is still being iterated on.
   */
  experimental?: boolean;
};

/**
 * One `[[requirement]]`, with every required key optional.
 */
export type PartialRequirement = {
  /**
   * Kebab-case identity, unique within the file. Required.
   */
  id?: string;
  /**
   * Whether the requirement is decided by a validator or by review. Required.
   */
  kind?: SuiteRequirementKind;
  /**
   * The RFC 2119 statement. Required.
   */
  text?: string;
  /**
   * Validator module paths relative to `validators/`.
   */
  validators?: Array<string>;
};

/**
 * `specifications/<name>/specification.toml`, with every required key optional.
 */
export type PartialSpecificationManifest = {
  /**
   * Kebab-case identity, unique among every specification in the suite.
   * Required.
   */
  id?: string;
  /**
   * The display name. Required.
   */
  name?: string;
  /**
   * A single inline plain-text line. Required.
   */
  summary?: string;
  /**
   * Where the rendered specification is seeded, relative to `specs/`.
   * Required.
   */
  path?: string;
  /**
   * The requirements, in the order they are presented.
   */
  requirement?: Array<PartialRequirement>;
};

/**
 * A `[[function.parameter]]`, with every required key optional.
 */
export type PartialDebugApiParameter = {
  /**
   * The parameter's name. Required.
   */
  name?: string;
  /**
   * What the parameter carries. Required.
   */
  description?: string;
};

/**
 * A `[[function]]`, with every required key optional.
 */
export type PartialDebugApiFunction = {
  /**
   * The property name the function is called by. Required.
   */
  name?: string;
  /**
   * Whether the function reports state or changes it. Required.
   */
  kind?: DebugApiFunctionKind;
  /**
   * The function's TypeScript signature. Required.
   */
  signature?: string;
  /**
   * What a query reports, or what a command changes. Required.
   */
  description?: string;
  /**
   * The parameters worth describing.
   */
  parameter?: Array<PartialDebugApiParameter>;
};

/**
 * A `[[module]]` reference, with every required key optional.
 */
export type PartialDebugApiModuleRef = {
  /**
   * The property name the module is reached by. Required.
   */
  name?: string;
  /**
   * The file declaring it, relative to the suite tree. Required.
   */
  path?: string;
  /**
   * What the module covers. Required.
   */
  description?: string;
};

/**
 * A debug API module, with every required key optional.
 */
export type PartialDebugApiModule = {
  /**
   * The `globalThis` property name. Declared by `debug-api.toml` alone, and
   * required there — which is a rule about where the module sits, so it is the
   * validator's to report rather than this type's.
   */
  handle?: string;
  /**
   * What this module covers. Required.
   */
  description?: string;
  /**
   * The functions this module defines.
   */
  function?: Array<PartialDebugApiFunction>;
  /**
   * The child modules this module reaches.
   */
  module?: Array<PartialDebugApiModuleRef>;
};

/**
 * `assets/<asset-id>/asset.toml`, with every required key optional.
 */
export type PartialAssetManifest = {
  /**
   * Kebab-case identity, identical to the folder name. Required.
   */
  id?: string;
  /**
   * The display name. Required.
   */
  name?: string;
  /**
   * The asset's format. Required.
   */
  kind?: SuiteAssetKind;
  /**
   * The `id` of the specification describing this asset. Required.
   */
  specification?: string;
  /**
   * The asset's files, relative to the asset folder. Required, and non-empty —
   * which is a rule about the value rather than about the key being there, so an
   * empty list is the validator's to report.
   */
  files?: Array<string>;
};

/**
 * `demos/<slug>/demo.toml`, with every required key optional.
 */
export type PartialDemoManifest = {
  /**
   * Kebab-case identity, matching the directory name. Required.
   */
  id?: string;
  /**
   * The display name. Required.
   */
  name?: string;
  /**
   * A one-line abstract. Required.
   */
  summary?: string;
  /**
   * The `id` of the specification whose mechanic this demonstrates. Required.
   */
  specification?: string;
};

/**
 * One `[[media]]` entry, with every required key optional.
 */
export type PartialShowcaseMediaEntry = {
  /**
   * The media file's name in the showcase directory. Required.
   */
  file?: string;
  /**
   * The short caption. Required.
   */
  name?: string;
};

/**
 * `showcase/showcase.toml`, with every required key optional.
 */
export type PartialShowcaseManifest = {
  /**
   * The carousel, in carousel order.
   */
  media?: Array<PartialShowcaseMediaEntry>;
};

/**
 * The `[sprite]` table, with its required key optional.
 */
export type PartialSpriteCase = {
  /**
   * The id of the asset the model produces. Required.
   */
  id?: string;
  /**
   * Whether the produced asset is a sprite sheet.
   */
  sheet?: boolean;
};

/**
 * The `[voxel]` table, with its required key optional.
 */
export type PartialVoxelCase = {
  /**
   * The id of the asset the model produces. Required.
   */
  id?: string;
  /**
   * Whether rigid-body animation is required.
   */
  animated?: boolean;
};

/**
 * A type table whose only key is the asset it targets, with that key optional.
 */
export type PartialAssetCase = {
  /**
   * The id of the asset the model produces. Required.
   */
  id?: string;
};

/**
 * The `[build]` table, with its required keys optional.
 */
export type PartialBuildCommands = {
  /**
   * Installs the produced implementation's dependencies. Required.
   */
  install?: string;
  /**
   * Produces the static build. Required.
   */
  build?: string;
};

/**
 * The `[toolchain]` table, with its required key optional.
 */
export type PartialToolchainCommands = {
  /**
   * Typechecks the implementation. Required.
   */
  typecheck?: string;
  /**
   * Lints the implementation.
   */
  lint?: string;
  /**
   * Format-checks the implementation.
   */
  format?: string;
  /**
   * Runs the implementation's own tests.
   */
  test?: string;
};

/**
 * `test-cases/<name>.toml`, with every required key optional.
 */
export type PartialTestCaseDefinition = {
  /**
   * The display name. Required.
   */
  name?: string;
  /**
   * The test case type. Required.
   */
  type?: SuiteTestCaseType;
  /**
   * The difficulty. Required.
   */
  difficulty?: SuiteDifficulty;
  /**
   * The engine slugs a run may select one entry from.
   */
  engines?: Array<string>;
  /**
   * The specification ids this test case covers; absent covers every one.
   */
  specifications?: Array<string>;
  /**
   * The Handlebars template handed to the harness. Required.
   */
  prompt?: string;
  /**
   * The cap on the session in hours.
   */
  max_runtime_hours?: number;
  /**
   * Whether the definition is kept out of the catalog by default.
   */
  experimental?: boolean;
  /**
   * The command run in the run container after seeding, before the harness.
   */
  init?: string;
  /**
   * The `[sprite]` table.
   */
  sprite?: PartialSpriteCase;
  /**
   * The `[voxel]` table.
   */
  voxel?: PartialVoxelCase;
  /**
   * The `[blender]` table.
   */
  blender?: PartialAssetCase;
  /**
   * The `[particle]` table.
   */
  particle?: PartialAssetCase;
  /**
   * The `[music]` table.
   */
  music?: PartialAssetCase;
  /**
   * The `[audio-fx]` table.
   */
  "audio-fx"?: PartialAssetCase;
  /**
   * `[workspaces]`: engine slug to starter workspace.
   */
  workspaces?: { [key in string]: string };
  /**
   * `[build]`.
   */
  build?: PartialBuildCommands;
  /**
   * `[toolchain]`.
   */
  toolchain?: PartialToolchainCommands;
};

/**
 * One specification folder, read through the partial model.
 */
export type PartialSpecificationFolder = {
  /**
   * The folder, relative to the suite tree.
   */
  dir: string;
  /**
   * `specification.toml`.
   */
  manifest: PartialSpecificationManifest;
  /**
   * The declared path of `specification.md`, relative to the suite tree.
   */
  prose: string;
  /**
   * The specification folders nested inside this one.
   */
  children: Array<PartialSpecificationFolder>;
};

/**
 * The debug API tree, read through the partial model.
 */
export type PartialDebugApi = {
  /**
   * `debug-api.toml`.
   */
  root: PartialDebugApiModule;
  /**
   * The module files under `debug-api/` that parse, keyed by their path
   * relative to the suite tree.
   */
  modules: { [key in string]: PartialDebugApiModule };
};

/**
 * One test case definition file, read through the partial model.
 */
export type PartialTestCaseFile = {
  /**
   * The file stem, which is the definition's slug.
   */
  slug: string;
  /**
   * The definition itself.
   */
  definition: PartialTestCaseDefinition;
};

/**
 * One asset folder, read through the partial model.
 */
export type PartialAssetFolder = {
  /**
   * The folder, relative to the suite tree. Its last segment is the asset's
   * id.
   */
  dir: string;
  /**
   * `asset.toml`.
   */
  manifest: PartialAssetManifest;
};

/**
 * One demonstration folder, read through the partial model.
 */
export type PartialDemoFolder = {
  /**
   * The folder, relative to the suite tree. Its last segment is the
   * demonstration's id.
   */
  dir: string;
  /**
   * `demo.toml`.
   */
  manifest: PartialDemoManifest;
};

/**
 * The suite showcase, read through the partial model.
 */
export type PartialShowcase = {
  /**
   * `showcase/showcase.toml`, the carousel.
   */
  manifest: PartialShowcaseManifest;
  /**
   * The declared path of `showcase.md`, relative to the suite tree.
   */
  description: string;
  /**
   * The media files sitting in the showcase directory, relative to the suite
   * tree.
   */
  media: Array<string>;
};

/**
 * The entity a problem is addressed to.
 *
 * One variant per entity kind the format defines, each carrying the identity
 * that kind is known by. The suite and the showcase are singular within a
 * version and carry none.
 *
 * The serde form is adjacently tagged — `{ "kind": "specification", "id": … }`,
 * with the `id` absent for the two variants that carry no identity — because The
 * Spec Cabinet's API hands a problem to a frontend that turns the address into
 * the editor surface it renders the message on.
 */
export type SuiteEntity =
  | { kind: "suite" }
  | { kind: "specification"; id: string }
  | {
      kind: "requirement";
      id: {
        /**
         * The `id` of the specification declaring it.
         */
        specification: string;
        /**
         * The requirement's own `id`, unique within that specification.
         */
        requirement: string;
      };
    }
  | { kind: "validator"; id: string }
  | { kind: "debug-api-node"; id: string }
  | { kind: "test-case"; id: string }
  | { kind: "asset"; id: string }
  | { kind: "demonstration"; id: string }
  | { kind: "reference-implementation"; id: string }
  | { kind: "showcase" };

/**
 * Which set of rules a problem broke.
 */
export type SuiteRule = "save" | "export";

/**
 * Where in a file a problem sits, for a problem that is about one file's text.
 */
export type SuiteLocation = {
  /**
   * The file, relative to the suite tree.
   */
  path: string;
  /**
   * The one-based line, when it is known.
   */
  line?: number;
  /**
   * The one-based column, when it is known.
   */
  column?: number;
};

/**
 * One problem: the rule it broke, and the entity that broke it.
 *
 * Serializable because every read and save response from The Spec Cabinet's API
 * carries the problems beside the model they were produced from.
 */
export type SuiteDiagnostic = {
  /**
   * Who the problem belongs to.
   */
  entity: SuiteEntity;
  /**
   * Whether the problem refuses a save or stands between a draft and an export.
   */
  rule: SuiteRule;
  /**
   * What the entity got wrong, as one sentence naming the value at fault.
   */
  message: string;
  /**
   * Where in a file the problem sits, for a file that does not parse.
   */
  location?: SuiteLocation;
};

/**
 * A TOML file of the tree that does not parse.
 *
 * Carried whole, so the file can be shown as it is and repaired in place, with
 * where the parse stopped so the repair starts at the right line.
 */
export type UnparsedFile = {
  /**
   * The file, relative to the suite tree.
   */
  path: string;
  /**
   * The entity the file would declare, identified by where it sits.
   */
  entity: SuiteEntity;
  /**
   * The file's text as it is on disk. Bytes that are not UTF-8 are replaced.
   */
  text: string;
  /**
   * What the parser said.
   */
  message: string;
  /**
   * The one-based line the parse failed at, when the parser located it.
   */
  line?: number;
  /**
   * The one-based column the parse failed at, when the parser located it.
   */
  column?: number;
};

/**
 * One whole suite tree — a draft or an exported version — in whatever state it is
 * in.
 */
export type PartialSuiteTree = {
  /**
   * `suite.toml`, the identity of the suite the tree belongs to. Read from the
   * suite folder rather than from the tree, so a save of the tree leaves it
   * alone.
   */
  suite: SuiteManifest;
  /**
   * `version.toml`, or `None` when the tree holds none or holds one that does
   * not parse.
   */
  manifest?: PartialVersionManifest;
  /**
   * The specification folders under `specifications/`, nested as they are on
   * disk.
   */
  specifications: Array<PartialSpecificationFolder>;
  /**
   * The debug API, when the tree holds a `debug-api.toml` that parses.
   */
  debug_api?: PartialDebugApi;
  /**
   * The test case definitions under `test-cases/`, one per file.
   */
  test_cases: Array<PartialTestCaseFile>;
  /**
   * The bundled assets under `assets/`, one per folder.
   */
  assets: Array<PartialAssetFolder>;
  /**
   * The demonstrations under `demos/`, one per folder.
   */
  demos: Array<PartialDemoFolder>;
  /**
   * The showcase, when the tree holds a `showcase/showcase.toml` that parses.
   */
  showcase?: PartialShowcase;
  /**
   * The trees the model references but does not hold.
   */
  trees: SuiteTrees;
  /**
   * Every TOML file the tree holds that does not parse, in the order the read
   * found them. The entity such a file would declare is absent from the model,
   * and a save of the model never writes over the file: its text is replaced
   * the way prose is, byte for byte.
   */
  unparsed?: Array<UnparsedFile>;
};
